      { title: 'الجدول ٤-٤ — ملخَّص النتائج', head: ['العيِّنة','الجلوكوز','البروتين','تركيز أيونات الكلوريد / g mL⁻¹'], rows: [['أ','غير موجود','موجود','0.006'],['ب','موجود','غير موجود','0.006'],['ج','غير موجود','غير موجود','0.012'],['د','غير موجود','غير موجود','0.006']] }
